        console.log("Initiative Order:");
        this.initiativeOrder.forEach((char, index) => {
            console.log(`${index + 1}. ${char.name} (Speed: ${char.speed})`);
        });
    }

    startCombat() {
        while (this.characters.some(char => char.health > 0)) {
            const currentCharacter = this.initiativeOrder[this.turnIndex];
            if (currentCharacter.health <= 0) {
                this.turnIndex = (this.turnIndex + 1) % this.initiativeOrder.length;
                continue;
            }

            console.log(`\n${currentCharacter.name}'s turn:`);

            if (currentCharacter.hasStatusEffect('stun')) {
