  constructor() {
    this.recipes = [];
    this.inventory = {};
  }

  // Add a recipe to the crafting system
  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  // Add items to the inventory
  addToInventory(item, quantity) {
    if (this.inventory[item]) {
      this.inventory[item] += quantity;
    } else {
      this.inventory[item] = quantity;
    }
  }

  // Check if a recipe can be crafted with the current inventory
  canCraft(recipe) {
    for (const [item, quantity] of Object.entries(recipe.requires)) {
      if (!this.inventory[item] || this.inventory[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  // Craft an item if possible
  craft(recipe) {
    if (this.canCraft(recipe)) {
      for (const [item, quantity] of Object.entries(recipe.requires)) {
        this.inventory[item] -= quantity;
      }
      if (recipe.produces) {
        this.addToInventory(recipe.produces.item, recipe.produces.quantity);
      }
      return true;
    }
    return false;
  }

  // Display the current inventory
  displayInventory() {
    console.log("Current Inventory:");
    for (const [item, quantity] of Object.entries(this.inventory)) {
      console.log(`${item}: ${quantity}`);
    }
  }
