class DialogueSystem {
  constructor() {
    this.flags = {};
    this.dialogues = {};
    this.currentDialogueKey = null;
  }

  // Method to add a dialogue with choices
  addDialogue(key, text, choices) {
    this.dialogues[key] = { text, choices };
  }

  // Method to start the dialogue system
  start(key) {
    this.currentDialogueKey = key;
    this.displayDialogue();
  }

  // Method to display the current dialogue
  displayDialogue() {
    const dialogue = this.dialogues[this.currentDialogueKey];
    console.log(dialogue.text);

    dialogue.choices.forEach((choice, index) => {
      console.log(`${index + 1}. ${choice.text}`);
    });

    // Prompt user for input
    const userInput = prompt("Enter your choice (number):");
    this.handleChoice(userInput);
  }

  // Method to handle user choice
  handleChoice(input) {
    const dialogue = this.dialogues[this.currentDialogueKey];
    const choiceIndex = parseInt(input, 10) - 1;

    if (choiceIndex >= 0 && choiceIndex < dialogue.choices.length) {
      const choice = dialogue.choices[choiceIndex];

      // Set flags if any
      if (choice.setFlags) {
        Object.keys(choice.setFlags).forEach(flag => {
          this.flags[flag] = choice.setFlags[flag];
        });
      }

      // Check flags if any
      if (choice.checkFlags) {
        let canProceed = true;
        Object.keys(choice.checkFlags).forEach(flag => {
          if (this.flags[flag] !== choice.checkFlags[flag]) {
            canProceed = false;
          }
        });

        if (!canProceed) {
          console.log("You cannot proceed with this choice.");
          this.displayDialogue();
          return;
        }
      }

      // Move to the next dialogue
      this.currentDialogueKey = choice.nextDialogue;
      this.displayDialogue();
    } else {
      console.log("Invalid choice. Please try again.");
      this.displayDialogue();
    }
  }
}

